// --- Chart Components ---
const WithoutFundingChart: React.FC<{ progress: number }> = ({ progress }) => {
  const dashOffset = interpolate(progress, [0, 1], [300, 0]);
  return (
    <svg width="100%" height="80" viewBox="0 0 260 80" style={{ transition: "none" }}>
      <path
        d="M 0 60 C 50 58, 100 65, 150 60 C 200 55, 230 62, 260 60"
        fill="none"
        stroke="#E2E8F0"
        strokeWidth="2"
        strokeDasharray={300}
        strokeDashoffset={dashOffset}
        style={{ transition: "none" }}
      />
    </svg>
  );
};

const WithFundingChart: React.FC<{ progress: number; themeColor: string }> = ({ progress, themeColor }) => {
  const dashOffset = interpolate(progress, [0, 1], [400, 0]);
  const fillOpacity = interpolate(progress, [0.5, 1], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const dotOpacity = interpolate(progress, [0.9, 1], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  return (
    <svg width="100%" height="80" viewBox="0 0 260 80" style={{ transition: "none" }}>
      <defs>
        <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor={themeColor} stopOpacity="0.2" />
          <stop offset="100%" stopColor={themeColor} stopOpacity="0" />
        </linearGradient>
      </defs>
      <path
        d="M 0 65 C 40 60, 80 70, 130 45 C 180 20, 220 35, 260 15"
        fill="none"
        stroke={themeColor}
        strokeWidth="3"
        strokeLinecap="round"
        strokeDasharray={400}
        strokeDashoffset={dashOffset}
        style={{ transition: "none" }}
      />
      <path
        d="M 0 65 C 40 60, 80 70, 130 45 C 180 20, 220 35, 260 15 L 260 80 L 0 80 Z"
        fill="url(#chartGradient)"
        opacity={fillOpacity}
        style={{ transition: "none" }}
      />
      <circle 
        cx="260" cy="15" r="5" fill={themeColor} 
        opacity={dotOpacity} 
        style={{ transition: "none" }}
      />
    </svg>
  );
};

// --- Helper Pill Component ---
const Pill: React.FC<{ delay: number; style?: React.CSSProperties; children: React.ReactNode }> = ({ delay, style, children }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const scale = spring({ frame: frame - delay, fps, config: { damping: 14 } });
  
  return (
    <div style={{
      position: 'absolute',
      backgroundColor: 'white',
      borderRadius: 100,
      padding: '12px 24px',
      boxShadow: '0 12px 32px rgba(0,0,0,0.08)',
      display: 'flex',
      alignItems: 'center',
      gap: 16,
      transform: `scale(${scale})`,
      zIndex: 10,
      transition: "none",
      ...style
    }}>
      {children}
    </div>
  );
};

// --- Main Animation Component ---
const DashboardAnimation: React.FC<DashboardAnimationProps> = ({
  backgroundColor = "#F0F4F8",
  transparentBackground = false,
  durationInSeconds = 6,
  mainAmount = 63750,
  outstandingAmount = 75000,
  reserveAmount = 11250,
  fundingTime = "24h",
  themeDarkBlue = "#1E3A8A",
  themeLightBlue = "#3B82F6",
  themeGreen = "#10B981",
  pill1Text = "INVOICE APPROVED",
  pill1Sub = "$12,450 Released",
  pill2Text = "B2B Verified",
  pill3Text = "Payroll Covered",
  pill4Text = "OPERATIONS CONTINUE",
  pill4Sub = "24h Funding",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const bgImage = transparentBackground ? 'none' : `radial-gradient(circle at 50% 50%, #FFFFFF 0%, ${backgroundColor} 100%)`;

  // Animation Utilities
  const useFadeIn = (delay: number) => {
    const opacity = interpolate(frame, [delay, delay + 15], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    const y = interpolate(frame, [delay, delay + 15], [20, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    return { opacity, transform: `translateY(${y}px)`, transition: "none" };
  };

  // Main Card Animation
  const cardProgress = spring({ frame, fps, config: { damping: 14 } });
  const cardScale = interpolate(cardProgress, [0, 1], [0.95, 1]);
  const cardOpacity = interpolate(cardProgress, [0, 1], [0, 1]);

  // Numbers Animation
  const countProgress = spring({ frame: frame - 20, fps, config: { damping: 12, mass: 1.5 } });
  const currentMainValue = Math.floor(interpolate(countProgress, [0, 1], [0, mainAmount]));
  
  const outstandingProgress = spring({ frame: frame - 25, fps, config: { damping: 12, mass: 1.5 } });
  const currentOutstanding = Math.floor(interpolate(outstandingProgress, [0, 1], [0, outstandingAmount]));
  
  const reserveProgress = spring({ frame: frame - 30, fps, config: { damping: 12, mass: 1.5 } });
  const currentReserve = Math.floor(interpolate(reserveProgress, [0, 1], [0, reserveAmount]));

  // Slider Animation
  const sliderProgress = spring({ frame: frame - 35, fps, config: { damping: 14 } });
  const sliderWidthPct = interpolate(sliderProgress, [0, 1], [0, 30]);

  // Chart Animation
  const chartProgress = spring({ frame: frame - 45, fps, config: { damping: 16, mass: 2 } });

  // Number Formatting helper
  const formatNumber = (num: number) => num.toLocaleString('en-US');
  const formattedMain = formatNumber(currentMainValue);
  const splitIndex = formattedMain.lastIndexOf(',');
  const mainDark = splitIndex !== -1 ? formattedMain.slice(0, splitIndex + 1) : formattedMain;
  const mainLight = splitIndex !== -1 ? formattedMain.slice(splitIndex + 1) : "";

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      backgroundImage: bgImage,
      fontFamily: interFamily,
      display: 'flex',
      justifyContent: 'center',
      alignItems: 'center',
      transition: "none"
    }}>
      
      {/* Container to bound the pills and card accurately */}
      <div style={{ position: 'relative', width: 1280, height: 640 }}>
        
        {/* Main Card */}
        <div style={{
          width: '100%', height: '100%',
          backgroundColor: 'white',
          borderRadius: 40,
          boxShadow: '0 30px 60px rgba(0,0,0,0.05)',
          padding: 64,
          display: 'flex',
          gap: 64,
          transform: `scale(${cardScale})`,
          opacity: cardOpacity,
          transition: "none"
        }}>
          
          {/* Left Column */}
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <div style={{ ...useFadeIn(10), display: 'flex', alignItems: 'center', gap: 12 }}>
              <div style={{ width: 40, height: 40, backgroundColor: '#EFF6FF', borderRadius: 12, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                <WalletIcon color={themeLightBlue} />
              </div>
              <div style={{ fontSize: 14, fontWeight: 700, color: '#94A3B8', letterSpacing: 1 }}>AVAILABLE WORKING CAPITAL</div>
            </div>
            
            <div style={{ ...useFadeIn(15), fontSize: 16, color: '#64748B', marginTop: 20, lineHeight: 1.6, maxWidth: 400 }}>
              Estimate how much cash may already be trapped in your unpaid invoices.
            </div>
            
            <div style={{ ...useFadeIn(20), display: 'flex', alignItems: 'baseline', marginTop: 40 }}>
              <span style={{ fontSize: 110, fontWeight: 800, color: themeDarkBlue, lineHeight: 1, letterSpacing: -3 }}>${mainDark}</span>
              <span style={{ fontSize: 110, fontWeight: 800, color: themeLightBlue, lineHeight: 1, letterSpacing: -3 }}>{mainLight}</span>
            </div>
            
            <div style={{ ...useFadeIn(25), display: 'flex', alignItems: 'center', gap: 8, marginTop: 16 }}>
              <TrendUpIcon color={themeLightBlue} />
              <div style={{ fontSize: 13, fontWeight: 700, color: '#94A3B8', letterSpacing: 1 }}>AVAILABLE TODAY</div>
            </div>
            
            <div style={{ ...useFadeIn(30), display: 'flex', gap: 24, marginTop: 48 }}>
              {/* Reserve Card */}
              <div style={{ flex: 1, backgroundColor: '#F8FAFC', borderRadius: 24, padding: 24, border: '1px solid #F1F5F9' }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: '#6366F1', letterSpacing: 1 }}>RESERVE</div>
                <div style={{ fontSize: 24, fontWeight: 800, color: '#0F172A', marginTop: 12 }}>${formatNumber(currentReserve)}</div>
                <div style={{ fontSize: 13, color: '#94A3B8', marginTop: 4, fontWeight: 500 }}>15% held</div>
              </div>
              
              {/* Funding Speed Card */}
              <div style={{ flex: 1, backgroundColor: '#F8FAFC', borderRadius: 24, padding: 24, border: '1px solid #F1F5F9' }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: themeGreen, letterSpacing: 1 }}>FUNDING SPEED</div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 12 }}>
                  <LightningIcon color="#0F172A" />
                  <div style={{ fontSize: 24, fontWeight: 800, color: '#0F172A' }}>{fundingTime}</div>
                </div>
                <div style={{ fontSize: 13, color: '#94A3B8', marginTop: 4, fontWeight: 500 }}>Same-day</div>
              </div>
            </div>
          </div>

          {/* Right Column */}
          <div style={{ flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
            <div style={{ ...useFadeIn(25), display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 24 }}>
              <div style={{ fontSize: 14, fontWeight: 700, color: '#94A3B8', letterSpacing: 1.5 }}>OUTSTANDING INVOICES</div>
              <div style={{ fontSize: 40, fontWeight: 800, color: '#0F172A', lineHeight: 1 }}>${formatNumber(currentOutstanding)}</div>
            </div>
            
            {/* Slider */}
            <div style={{ ...useFadeIn(30) }}>
              <div style={{ width: '100%', height: 12, backgroundColor: '#F1F5F9', borderRadius: 6, position: 'relative' }}>
                <div style={{ 
                  position: 'absolute', left: 0, top: 0, height: '100%', 
                  width: `${sliderWidthPct}%`, backgroundColor: themeLightBlue, borderRadius: 6,
                  transition: "none"
                }} />
                <div style={{
                  position: 'absolute', left: `${sliderWidthPct}%`, top: '50%',
                  transform: 'translate(-50%, -50%)',
                  width: 28, height: 28, backgroundColor: 'white',
                  border: `4px solid ${themeLightBlue}`, borderRadius: '50%',
                  boxShadow: `0 0 0 8px ${themeLightBlue}20`,
                  transition: "none"
                }} />
              </div>
              <div style={{ fontSize: 13, color: '#94A3B8', marginTop: 16, fontWeight: 600 }}>$5K</div>
            </div>
            
            {/* Charts Container */}
            <div style={{ ...useFadeIn(35), marginTop: 48, borderRadius: 24, border: '1px solid #F1F5F9', backgroundColor: '#FAFAFC', padding: 32, display: 'flex', gap: 32 }}>
              <div style={{ flex: 1, borderRight: '1px dashed #E2E8F0', paddingRight: 32 }}>
                <div style={{ fontSize: 12, fontWeight: 700, color: '#94A3B8', letterSpacing: 1, marginBottom: 24 }}>WITHOUT FUNDING</div>
                <WithoutFundingChart progress={chartProgress} />
              </div>
              <div style={{ flex: 1 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 24 }}>
                  <div style={{ fontSize: 12, fontWeight: 700, color: themeLightBlue, letterSpacing: 1 }}>WITH OPENINVOICES</div>
                  <div style={{ width: 6, height: 6, backgroundColor: themeLightBlue, borderRadius: '50%', boxShadow: `0 0 0 4px ${themeLightBlue}30` }} />
                </div>
                <WithFundingChart progress={chartProgress} themeColor={themeLightBlue} />
              </div>
            </div>
          </div>
          
        </div>

        {/* Floating Pills - Positioned relative to the 1280x640 bounding box */}
        <Pill delay={40} style={{ top: -30, left: -40, borderRadius: 32, padding: '16px 24px' }}>
          <div style={{ width: 40, height: 40, backgroundColor: themeGreen, borderRadius: '50%', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
            <CheckIcon color="white" />
          </div>
          <div>
            <div style={{ fontSize: 12, fontWeight: 700, color: '#94A3B8', letterSpacing: 1, marginBottom: 4 }}>{pill1Text}</div>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#0F172A' }}>{pill1Sub}</div>
          </div>
        </Pill>

        <Pill delay={50} style={{ top: 40, right: -30, padding: '12px 20px' }}>
          <ShieldCheckIcon color={themeLightBlue} />
          <div style={{ fontSize: 15, fontWeight: 700, color: '#0F172A' }}>{pill2Text}</div>
        </Pill>

        <Pill delay={60} style={{ top: 260, right: -50, padding: '12px 20px' }}>
          <div style={{ width: 24, height: 24, backgroundColor: '#DCFCE7', borderRadius: '50%', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
            <DollarIcon color="#16A34A" />
          </div>
          <div style={{ fontSize: 15, fontWeight: 700, color: '#0F172A' }}>{pill3Text}</div>
        </Pill>

        <Pill delay={70} style={{ bottom: -30, right: 80, borderRadius: 32, padding: '16px 24px' }}>
          <div style={{ width: 40, height: 40, backgroundColor: themeLightBlue, borderRadius: 12, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
            <HeartbeatIcon color="white" />
          </div>
          <div>
            <div style={{ fontSize: 12, fontWeight: 700, color: '#94A3B8', letterSpacing: 1, marginBottom: 4 }}>{pill4Text}</div>
            <div style={{ fontSize: 18, fontWeight: 800, color: '#0F172A' }}>{pill4Sub}</div>
          </div>
        </Pill>

      </div>
    </AbsoluteFill>
  );
};

export default DashboardAnimation;